using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EnhanceWithNewActionAction", menuName = "Data/Battle/Battle Actions/Moonie/EnhanceWithNewAction Action")]
public class EnhanceWithNewActionAction : EnhanceAction
{
	[SerializeField]
	private BattleAction newBattleAction;

	[SerializeField]
	private bool addJapaneseVisualBugFix;

	[SerializeField]
	private bool anyDice;

	public BattleAction NewBattleAction => newBattleAction;

	public bool AddJapaneseVisualBugFix => addJapaneseVisualBugFix;

	public bool AnyDice => anyDice;

	protected override void EnhanceFirstAction(DiceInstance diceInstance)
	{
		diceInstance.ActionFace.BattleAction = newBattleAction;
		diceInstance.ActionFace.ActionValue = newActionValue;
		diceInstance.ActionFace.UpdateActionValueModifier();
	}

	protected override void EnhanceSecondAction(DiceInstance diceInstance)
	{
		diceInstance.ActionFace.SecondBattleAction = newBattleAction;
		diceInstance.ActionFace.SecondActionValue = newActionValue;
		diceInstance.ActionFace.UpdateActionValueModifier();
	}

	protected override void EnhanceBothActions(DiceInstance diceInstance)
	{
		diceInstance.ActionFace.BattleAction = newBattleAction;
		diceInstance.ActionFace.ActionValue = newActionValue;
		diceInstance.ActionFace.SecondBattleAction = newBattleAction;
		diceInstance.ActionFace.SecondActionValue = newActionValue;
		diceInstance.ActionFace.UpdateActionValueModifier();
	}
}
